const SEED=window.ChefSeed||[],HERO='https://images.unsplash.com/photo-1577219491135-ce391730fb2c?w=1200&q=80',demoAgenda=c=>{let h=0;for(const ch of c.id)h=(h*31+ch.charCodeAt(0))>>>0;const off=[],t=new Date();for(let i=0;i<120;i++){h=(h*1664525+1013904223)>>>0;if((h>>>8)%100<30){const d=new Date(t.getFullYear(),t.getMonth(),t.getDate()+i);off.push(d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0'))}}const r={...c,agenda:{off}};if(c.marmita){const md=c.dishes.filter(d=>d.marmita);const mk=(id,name,n,total)=>{const ds=md.slice(0,n);if(ds.length<2)return null;const items={},base=Math.floor(total/ds.length);ds.forEach((d,i)=>{items[String(d.id)]=base+(i<total-base*ds.length?1:0)});return {id,name,items}};r.marmita={...c.marmita,kits:[mk('k1','Semana leve',2,c.marmita.min),mk('k2','Semana completa',4,Math.ceil(c.marmita.min*1.5))].filter(Boolean)}}return r},demoList=()=>window.ChefDemo&&window.ChefDemo.enabled===false?[]:SEED.map(demoAgenda);
try{DATA=C.withDemo(C.readData(localStorage,SEED),demoList())}catch(e){DATA=C.withDemo(C.normalizeData({},SEED),demoList());storageBlocked=true;storageError='Não foi possível ler os dados salvos. A demonstração foi aberta sem sobrescrever seu histórico.'}
