function opcoesInfo(c){const o=C.opcoes(c),on=C.OPCOES.filter(x=>o[x[0]]).map(x=>x[1].replace(/^(Atendo |Faço |Deixo |Levo |Ofereço |Cozinho |Cuido de )/,m=>VERBO[m]));return on.length?'<div class="opcoes-info"><b>Como este chef atende</b><ul>'+on.map(t=>'<li>'+esc(t)+'</li>').join('')+'</ul>'+(o.criancas?'':'<p class="form-help">Este chef não atende eventos com crianças.</p>')+'</div>':''}
function marmitaInfo(c){const m=c.marmita;if(!m)return '';return '<div class="marmita-info"><b>Faz marmitas</b><span>'+m.freq.map(f=>C.FREQ[f].label.toLowerCase()).join(' · ')+' · a partir de '+money(m.price)+' por marmita · mínimo de '+m.min+' por entrega · '+m.modes.map(x=>x==='entrega'?'entrega':'preparo na sua casa').join(' ou ')+'</span></div>'}
function gallery(c){return c.gallery.length?'<div class="grid">'+c.gallery.map((p,i)=>'<button class="tile" data-a="photo" data-chef="'+esc(c.id)+'" data-index="'+i+'" aria-label="Abrir foto: '+esc(p.caption||'Foto '+(i+1))+'">'+img(p.url,p.caption||'Foto do portfólio',c.name,'')+'<span class="tile-label">'+esc(p.caption||'Da nossa cozinha')+'</span></button>').join('')+'</div>':'<p class="empty">O portfólio está sendo preparado.</p>'}
