function syncMix(){const c=chef(S.order.chef),m=S.order.m,sum=mixSum(m);if(sum>0){m.qty=sum;S.order.dishes=c.dishes.filter(d=>m.mix[String(d.id)]).map(d=>d.id)}else S.order.dishes=[];const q=$('#o_mqty');if(q){q.value=m.qty;q.readOnly=sum>0}const t=$('#mix-total');if(t)t.textContent=mixTotalText(c);updateSummary()}
function marmitasPage(){const list=DATA.chefs.filter(c=>c.marmita&&(!S.city||String(c.cities).includes(S.city)));return '<div class="ghead"><h1>Marmitas</h1></div><p class="mut" style="margin:-10px 0 18px">Planos semanais, quinzenais ou mensais, com as sugestões do chef ou montados do seu jeito.</p><div class="search-tools"><select id="mcity" aria-label="Filtrar por cidade"><option value="">Todas as cidades</option>'+cities().map(x=>'<option '+(x===S.city?'selected':'')+'>'+esc(x)+'</option>').join('')+'</select></div><div class="result-meta"><span role="status">'+list.length+' '+(list.length===1?'chef faz marmitas':'chefs fazem marmitas')+'</span></div>'+(list.length?'<div class="chef-grid">'+list.slice(0,S.limit).map(c=>{const m=c.marmita,k=(m.kits||[]).length;return '<div class="chef-card"><a href="#/chef/'+hash(c.id)+'" class="chef-card-title" style="padding:16px 16px 0">'+img(c.avatar,'',c.name)+'<div><h3>'+esc(c.name)+'</h3><p class="location">'+esc(c.cities||'Local a combinar')+'</p></div></a><div class="chef-card-content"><p class="specialty">A partir de '+money(m.price)+' por marmita · mínimo de '+m.min+' por entrega</p><p class="form-help">'+m.freq.map(f=>C.FREQ[f].label.toLowerCase()).join(' · ')+(k?' · '+k+' '+(k===1?'sugestão':'sugestões')+' do chef':'')+'</p><div class="acts"><a class="b b1" href="#/pedido/'+hash(c.id)+'/marmita">Ver marmitas</a></div></div></div>'}).join('')+'</div>':empty('Nenhum chef de marmitas por aqui ainda','Tente outra cidade.','#/marmitas','Ver todas'))}
